package org.codex.nfsugpreview;
import android.app.*;import android.os.*;import java.io.*;import java.nio.*;import java.nio.file.*;import java.util.*;import org.json.*;
public final class MenuCaptureGpuInstrumentation extends MenuTextGpuInstrumentation {
 byte[] colors(NativeMenuText text){byte[] rgba=new byte[153600];text.rgba().get(rgba);return rgba;}
 @Override public void onStart(){Bundle result=new Bundle();boolean live=false;try{File dir=getTargetContext().getFilesDir();byte[] state=Files.readAllBytes(new File(dir,"menu-capture.state").toPath());ArrayList<NativeMenuText> nonempty=new ArrayList<>();Set<String> hashes=new HashSet<>();int frames=0;long firstRefresh=-1,lastRefresh=-1;NativeMenuText last=null;String lastHash=null;startGl();live=true;
 try(NativeCore core=new NativeCore(new File(dir,"menu-capture.gba").getPath())){ok(core.loadCheckpoint(state)&&core.capture(true)&&core.captureLayers(true)&&NativeMenuCapture.enable(core,true),"capture setup");for(int i=0;i<90;i++){ok(core.step(i>=15&&i<17?128:0)==1,"original step");byte[] bundle=NativeMenuCapture.capture(core);if(bundle==null)continue;NativeMenuText text=NativeMenuText.fromBundle(bundle);if(firstRefresh<0)firstRefresh=text.refresh;ok(lastRefresh<text.refresh,"capture refresh order");lastRefresh=text.refresh;byte[] rgba=colors(text);String hash=verify(text,rgba,240,160,240);hashes.add(hash);frames++;int count=0;for(int k=3;k<rgba.length;k+=4)if(rgba[k]!=0)count++;if(count>0)nonempty.add(text);last=text;lastHash=hash;}}
 ok(frames==89&&hashes.size()>1&&nonempty.size()>=3,"dynamic text coverage");for(int i:new int[]{0,nonempty.size()/2,nonempty.size()-1}){NativeMenuText text=nonempty.get(i);verify(text,colors(text),3840,2160,3240);}endGl();live=false;startGl();live=true;ok(verify(last,colors(last),240,160,240).equals(lastHash),"retained capture/context recreation");
 JSONObject report=new JSONObject();report.put("result","PASS_ANDROID_DYNAMIC_MENU_CAPTURE_GPU");report.put("captured_refreshes",frames);report.put("first_refresh",firstRefresh);report.put("last_refresh",lastRefresh);report.put("distinct_native_images",hashes.size());report.put("nonempty_refreshes",nonempty.size());report.put("four_k_refreshes",3);report.put("pixel_checks",checks);report.put("covered_samples",covered);report.put("transparent_samples",transparent);report.put("context_recreated",true);report.put("renderer",renderer);report.put("game_steps",90);report.put("real_time_pacing",false);try(FileOutputStream out=getTargetContext().openFileOutput("menu-capture-gpu-report.json",0)){out.write(report.toString(2).getBytes("UTF-8"));}result.putString("stream",report.toString());finish(Activity.RESULT_OK,result);}catch(Throwable e){android.util.Log.e("NFSUGMenuDynamicGPU","Failed",e);result.putString("stream","FAIL: "+e);finish(Activity.RESULT_CANCELED,result);}finally{if(live)endGl();}}
}
